UPDATE t_worker
   SET name = #{name}, phone = #{phone}, skill_tags = #{skillTags},
       current_orders = #{currentOrders}, location = #{location}, status = #{status}
 WHERE worker_id = #{workerId}

UPDATE t_worker
   SET current_orders = GREATEST(COALESCE(current_orders, 0) + #{delta}, 0)
 WHERE worker_id = #{workerId}
